for sid, pairs in T.items():
    src = f'pengguna/simulasi/{sid}.html'; s = open(src).read()
    for a, b in COMMON + pairs:
        if a not in s:
            if (a, b) in COMMON: continue
            raise SystemExit(f'{sid}: tak jumpa {a!r}')
        s = s.replace(a, b)
    open(f'pengguna/simulasi/{sid}_en.html', 'w').write(s)
    print('ok', sid)
